// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(address actor, uint256 v1, uint256 v2) public {
        vm.assume(v1 <= VALUE_CAP);
        vm.assume(v2 <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        v1 = bound(v1, 1, 10 ether);
        v2 = bound(v2, 1, 10 ether);

        vm.deal(actor, v1 + v2);
        vm.prank(actor);
        c.Put{value: v1}(0);
        vm.prank(actor);
        c.Put{value: v2}(0);

        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == v1 + v2);
    }
}
